-- GENERATED by `wfj generate` from data/gossip/gossip-3c.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3c0252a7cc3ef312"] = { "Questi frammenti brillano di un riflesso innaturale. È chiaro che celano un potere profondo.", "." },
  ["3c06ae54adeaf548"] = { "Dovrai darmi un attimo, {class}: i naga ci stanno attaccando proprio adesso. Ti parlerò non appena l'attacco sarà finito!", "." },
  ["3c0d07b2c202ca38"] = { "Maledetti mortali! Tutti i miei piani di vendetta, tutto il mio odio... tutto ridotto in cenere...", "." },
  ["3c16199b76106a29"] = { "Devi avere reputazione Osannato presso i tauren di ⟦Thunder Bluff=Picco del Tuono⟧ prima che io ti insegni a cavalcare, {class}.", "." },
  ["3c1c8ac36d5cce34"] = { "<Il sergente Stormpike fa il saluto militare.>\n\nNome, grado e numero di matricola, soldato! È l'unica informazione che darai mai a quei luridi cani dei Lupi Bianchi!", "." },
  ["3c22f9df1e75b2a4"] = { "Pensa ai fatti tuoi. La mia commissione non richiede la tua attenzione.", "." },
  ["3c2731429e952d58"] = { "Stregoni... Non mi piace quella gente. Come quel Grimrizz che si è sistemato fuori dalla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧. Per colpa sua la birra lì diventerà sgasata! Stregoni... bah!", "." },
  ["3c2891460f4e74d1"] = { "Khara canticchia una vecchia melodia nanica mentre cucina.", "." },
  ["3c3069d6e4586916"] = { "Sì, {class}?", "." },
  ["3c38b2fec588570b"] = { "Se hai intenzione di avventurarti nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, vieni a parlarmi. Potrei avere del lavoro per te.", "." },
  ["3c48d177aac9af36"] = { "Centinaia di diagrammi e schemi di ogni tipo cominciano a prendere forma sulle pagine del libro. Alcuni diagrammi li riconosci, altri ti restano estranei eppure familiari.", "." },
  ["3c4eaab6fb106123"] = { "E ora... il passo finale!", "." },
  ["3c4ebd91eb0b5630"] = { "Nella sala delle udienze del re troverai dama Hoteshem. Può aiutarti a raggiungere il ⟦Arathi Basin=Bacino d'Arathi⟧, dove la ⟦The League of Arathor=Lega di Arathor⟧ ha bisogno di aiuto contro i ⟦The Defilers=Profanatori⟧.", "." },
  ["3c5237b5dc862531"] = { "L'imperatore Thaurissan non vuole essere disturbato! Tornate indietro subito o affrontate la vostra rovina, deboli mortali!", "." },
  ["3c599235eebc42a8"] = { "Chi osa evocarmi?", "." },
  ["3c5aaadd1d92e521"] = { "Sì. Dammi l'incantesimo per evocare l'avatar.", "." },
  ["3c5ebb3b3331d6ca"] = { "Sembra che ti servano un paio di incantamenti. Sei nel posto giusto!", "." },
  ["3c6368379103cf3e"] = { "Grazie mille, {name}. Non ce l'avremmo fatta senza di te. Ah, e se prima avevo accennato a qualcosa per ripagarti di averci salvato, be'... puoi scordartelo!", "." },
  ["3c65cd8c014df631"] = { "Vorrei un nuovo invito alla Celebrazione della Luna.", "." },
  ["3c6b0d4ac3004df1"] = { "Druidi e i vostri sciocchi cambi di forma. Vediamoli all'opera!", "." },
  ["3c6f43ff5bdd4ac8"] = { "Che lusinga, ma davvero non mi interessa... Cosa? Vuoi sapere dove imparare l'incantamento? Oh, che imbarazzo! Be', dovresti... di sicuro potresti... andare da, ehm... Taladan! Sì, va' da Taladan, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧!", "." },
  ["3c717724dff46365"] = { "%s ti prosciuga il mana e si trasforma in pietra.", "." },
  ["3c7a1a4d568c2f59"] = { "Ne è stato aperto uno sulla Terrazza dei Mercanti. Se prendi il sentiero che dalla banca porta a sud-est, dovrebbe essere facile da trovare.", "." },
  ["3c7f8fb3e95d1eba"] = { "L'influenza della Shattered Hand domina queste terre. Siamo il velo che copre Kalimdor: i protettori, la polizia, i giudici, la giuria e, alla fine, i boia. Vediamo tutto, sappiamo tutto.\n\nSei <cresciuto/cresciuta> molto nel tempo che hai passato al servizio della Hand, {name}. È giunto il momento di mandarti sul campo.\n\nSei <pronto/pronta> ad affrontare la tua prossima missione?", "." },
  ["3c7fe1a48c7f29f7"] = { "Ops! Era un po' fuori. Non ho nemmeno colpito il bersaglio!", "." },
  ["3c82bdeb0bb105be"] = { "Se speri di imparare a fare il sarto, devi proprio cercare Me'Lynn. Risiede nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus.", "." },
  ["3c869c96977d69a0"] = { "Mi piace costruire cose. Certo, farle saltare in aria mi piace ancora di più!", "." },
  ["3c881cf512babcbe"] = { "Non può essere. Non si potrebbe mai permettere a un Dio Antico di entrare in questo mondo. Le conseguenze sarebbero... Oh, cielo!", "." },
  ["3c8b0e910f7e536c"] = { "Continua, per favore.", "." },
  ["3c91797f917fd322"] = { "La vera maestria va guadagnata! Ora sta a te guadagnartela...", "." },
  ["3c9598faf057efc3"] = { "Ti do il benvenuto a Theramore, {name}.\n\nPerdona i miei modi bruschi e il poco tempo per i convenevoli, ma la mia città viene prima di tutto. Troppe cose minacciano il nostro stile di vita e l'integrità dell'⟦Alliance=Alleanza⟧. Devo restare sempre vigile contro forze che sfuggono al nostro controllo, se voglio che la mia gente resti al sicuro e felice.\n\nForse avremo più tempo per parlare in seguito.", "." },
  ["3c9680ae5bbb73f5"] = { "I pesci hanno mai sete?", "." },
  ["3c981a63b831cc51"] = { "Ho ripreso il controllo! Tutti quanti, tornate ai vostri posti!", "." },
  ["3c9c7f65a3ab8dac"] = { "Cosa ne sai?", "." },
  ["3c9e614fb46b24d2"] = { "%s si libera dal suo sonno di pietra!", "." },
  ["3c9f178b9babb917"] = { "Il tuo futuro è avvolto nella nebbia. Concentrati e chiedi di nuovo.", "." },
  ["3c9f9e8585bd1760"] = { "Tiro quasi perfetto! È un po' fuori, ma capisco perché Grumlar lo mancherebbe. Non centrerebbe nemmeno il lato di un fienile.", "." },
  ["3ca3b8bf42efeea0"] = { "Ho appena ricevuto notizie in merito. Al momento abbiamo $2021w peacebloom su $2020w, $2050w firebloom su $2051w e $2054w fiori di loto purpureo su $2055w richiesti.", "." },
  ["3ca63548a3f31cba"] = { "Ciao, {name}. Senza rancore, d'accordo?", "." },
  ["3cae78b239930147"] = { "Cinque biglietti o duecentocinquanta, non importa, amico: vincono tutti!", "." },
  ["3cbe49ee9b95d6e7"] = { "⟦Kah Mistrunner=Kah Cavalca Nebbia⟧, al Mountaintop Bait & Tackle sull'altura più alta, ti mostrerà come trovare la pace interiore e la serenità mentre peschi il tuo prossimo pasto.", "." },
  ["3cc2152a16f9178b"] = { "Gli spiriti del vento ci avranno anche lasciati, ma il potere degli elementi non è del tutto fuori portata per chi ha la pazienza di cercarlo.\r\n\nSe sei <un/una> {class} <iniziato/iniziata> a queste vie, posso aiutarti a comprenderle.", "." },
  ["3cc4f9b09cf0aba0"] = { "Karnik, amico mio, vorrei tanto rivederti con i miei occhi, ma dobbiamo parlare di Ragnaros. La sua influenza si sta diffondendo.", "." },
  ["3cc58c0c09937daf"] = { "%s si passa l'indice sulla gola, mimando un taglio.", "." },
  ["3cc8c2472923b812"] = { "Ti prego, campione, proteggi il nostro popolo.", "." },
  ["3cce84146ecb4658"] = { "Ok, ora andiamocene da qui!", "." },
  ["3cd1e2f8a996e2b8"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Boots=Stivali di Cuoio Selvatico⟧?", "." },
  ["3cd32fa019140f89"] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ non fallirà nella sua missione!", "." },
  ["3cd4cad92e74e21c"] = { "Lavori il cuoio di mestiere, vero? È quel leggero odore di pelli conciate: lo riconoscerei ovunque.\n\nMio padre mi parlava di un famoso artigiano che viveva a ⟦Southwind Village=Vento del Sud⟧ secoli fa. È un peccato che ora il villaggio sia in rovina.", "." },
  ["3cd5df67777eff4a"] = { "Io... non so bene cosa mi abbia portato qui...\n\nMi sembra di ricordare un viaggio... una zattera...", "." },
  ["3cdca2b08ddf07ca"] = { "Sono felice che tu l'abbia chiesto. Troverai ser Malory Wheeler nel Royal Quarter, al cospetto della nostra Dama Oscura.", "." },
  ["3cdd0bf7fa80d467"] = { "Aspettano di schiacciare la vita dei nostri piccoli. Di massacrare tutti quelli che trovano sul loro cammino. Questo fanno per il loro dio.", "." },
  ["3cde6c4ddf81e71c"] = { "Frazier va giù! Frazier va giù! Va giù... eh? Quello non era Frazier?", "." },
  ["3cee35cfee2d5757"] = { "<Resta in silenzio>", "." },
  ["3cf1722af894056d"] = { "Le ⟦Eastern Plaguelands=Terre Infette Orientali⟧ sono sotto attacco in questo momento?", "." },
  ["3cfefadfd72ed5a5"] = { "Scappate pure, sciocchi! Il vostro destino è comunque segnato!", "." },
})
